{
  "root": "main_stack",
  "state": {
    "cupcakeIngredients": [
      { "ingredient": "All-purpose flour", "quantity": "1 ½ cups (180g)" },
      { "ingredient": "Baking powder", "quantity": "1 ½ teaspoons" },
      { "ingredient": "Salt", "quantity": "½ teaspoon" },
      { "ingredient": "Unsalted butter, softened", "quantity": "½ cup (113g)" },
      { "ingredient": "Granulated sugar", "quantity": "1 cup (200g)" },
      { "ingredient": "Large eggs, at room temperature", "quantity": "2" },
      { "ingredient": "Pure vanilla extract", "quantity": "1 teaspoon" },
      { "ingredient": "Whole milk, at room temperature", "quantity": "½ cup (120ml)" }
    ],
    "frostingIngredients": [
      { "ingredient": "Unsalted butter, softened", "quantity": "1 cup (226g)" },
      { "ingredient": "Powdered sugar, sifted", "quantity": "3-4 cups (360-480g)" },
      { "ingredient": "Whole milk or heavy cream", "quantity": "1-2 tablespoons" },
      { "ingredient": "Pure vanilla extract", "quantity": "1 teaspoon" },
      { "ingredient": "Pinch of salt", "quantity": "Optional" }
    ],
    "cupcakeInstructions": [
      { "step": 1, "text": "Preheat oven to 350°F (175°C). Line a 12-cup muffin tin with paper liners." },
      { "step": 2, "text": "In a medium bowl, whisk together flour, baking powder, and salt. Set aside." },
      { "step": 3, "text": "In a large bowl, cream together softened butter and granulated sugar until light and fluffy (about 2-3 minutes)." },
      { "step": 4, "text": "Beat in eggs one at a time, then stir in vanilla extract." },
      { "step": 5, "text": "Gradually add the dry ingredients to the wet ingredients, alternating with the milk, beginning and ending with the dry ingredients. Mix until just combined; do not overmix." },
      { "step": 6, "text": "Divide batter evenly among the prepared muffin cups, filling each about two-thirds full." },
      { "step": 7, "text": "Bake for 18-22 minutes, or until a wooden skewer inserted into the center comes out clean. Let cool in the muffin tin for a few minutes before transferring to a wire rack to cool completely." }
    ],
    "frostingInstructions": [
      { "step": 1, "text": "In a large bowl, beat softened butter with an electric mixer until creamy (about 2 minutes)." },
      { "step": 2, "text": "Gradually add powdered sugar, 1 cup at a time, beating well after each addition. If the frosting is too thick, add milk/cream 1 tablespoon at a time until desired consistency is reached." },
      { "step": 3, "text": "Beat in vanilla extract and a pinch of salt (if using). Continue beating on medium-high speed for another 2-3 minutes until light and fluffy." },
      { "step": 4, "text": "Once cupcakes are completely cool, pipe or spread frosting onto them." }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_text",
        "tabs_component"
      ]
    },
    "title_text": {
      "type": "Text",
      "props": {
        "text": "Classic Vanilla Cupcakes",
        "variant": "h1"
      },
      "children": []
    },
    "tabs_component": {
      "type": "Tabs",
      "props": {
        "tabs": [
          {
            "title": "Ingredients",
            "child": "ingredients_content_stack"
          },
          {
            "title": "Instructions",
            "child": "instructions_content_stack"
          }
        ]
      },
      "children": []
    },
    "ingredients_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "paddingVertical": 16
      },
      "children": [
        "cupcake_ingredients_heading",
        "cupcake_ingredients_table",
        "frosting_ingredients_heading",
        "frosting_ingredients_table"
      ]
    },
    "cupcake_ingredients_heading": {
      "type": "Text",
      "props": {
        "text": "Cupcake Ingredients",
        "variant": "h2"
      },
      "children": []
    },
    "cupcake_ingredients_table": {
      "type": "Table",
      "props": {
        "statePath": "/cupcakeIngredients",
        "columns": [
          {
            "key": "ingredient",
            "label": "Ingredient"
          },
          {
            "key": "quantity",
            "label": "Quantity"
          }
        ],
        "domain": "generic",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "frosting_ingredients_heading": {
      "type": "Text",
      "props": {
        "text": "Vanilla Buttercream Frosting Ingredients",
        "variant": "h2"
      },
      "children": []
    },
    "frosting_ingredients_table": {
      "type": "Table",
      "props": {
        "statePath": "/frostingIngredients",
        "columns": [
          {
            "key": "ingredient",
            "label": "Ingredient"
          },
          {
            "key": "quantity",
            "label": "Quantity"
          }
        ],
        "domain": "generic",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "instructions_content_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "paddingVertical": 16
      },
      "children": [
        "cupcake_instructions_heading",
        "cupcake_instructions_list",
        "frosting_instructions_heading",
        "frosting_instructions_list"
      ]
    },
    "cupcake_instructions_heading": {
      "type": "Text",
      "props": {
        "text": "Cupcake Instructions",
        "variant": "h2"
      },
      "children": []
    },
    "cupcake_instructions_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "repeat": {
        "statePath": "/cupcakeInstructions",
        "key": "step"
      },
      "children": [
        "cupcake_instruction_item_stack"
      ]
    },
    "cupcake_instruction_item_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "start"
      },
      "children": [
        "cupcake_instruction_step_text",
        "cupcake_instruction_text"
      ]
    },
    "cupcake_instruction_step_text": {
      "type": "Text",
      "props": {
        "text": {
          "$template": "Step ${$item.step}:"
        },
        "variant": "label"
      },
      "children": []
    },
    "cupcake_instruction_text": {
      "type": "Text",
      "props": {
        "text": {
          "$item": "text"
        },
        "variant": "body"
      },
      "children": []
    },
    "frosting_instructions_heading": {
      "type": "Text",
      "props": {
        "text": "Vanilla Buttercream Frosting Instructions",
        "variant": "h2"
      },
      "children": []
    },
    "frosting_instructions_list": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "repeat": {
        "statePath": "/frostingInstructions",
        "key": "step"
      },
      "children": [
        "frosting_instruction_item_stack"
      ]
    },
    "frosting_instruction_item_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "start"
      },
      "children": [
        "frosting_instruction_step_text",
        "frosting_instruction_text"
      ]
    },
    "frosting_instruction_step_text": {
      "type": "Text",
      "props": {
        "text": {
          "$template": "Step ${$item.step}:"
        },
        "variant": "label"
      },
      "children": []
    },
    "frosting_instruction_text": {
      "type": "Text",
      "props": {
        "text": {
          "$item": "text"
        },
        "variant": "body"
      },
      "children": []
    }
  }
}
